        if territory_set:
            terr_bonus = 0 if (nx, ny) in territory_set else 1

        # Avoid obvious danger: adjacent to opponent or their trail.
        danger = 0
        if opp_dist == 0:
            danger += 8
        elif opp_dist == 1:
            danger += 4
        elif opp_dist == 2:
            danger += 1

        if (nx, ny) in threat_cells:
            danger += 3

        # Mild inertia to reduce dithering.
        inertia = 0 if dx == 0 and dy == 0 else 1

        # Composite score: lower is better.
        score = goal_dist * 6 + danger * 10 + terr_bonus * 2 + inertia

        # If no resources, be more aggressive but not suicidal.
        if not resources:
